default:
	// The published envelope carries a session only for the operations that act on one, so the fixture mirrors
	// the protocol instead of answering every command with an id the CLI would be entitled to adopt.
	sessionID := ""
	resultSession := ""
	if p.mode == "identity-substitution" && method == "session.list" {
		// A host that reports the most recently active session on a listing. Accepting that as *the* session
		// would let any reply rename the conversation, which is the substitution mutant V12 probes for.
		sessionID, resultSession = "sess-from-list", "sess-from-list"
	}
	switch method {
	case "session.create":
		sessionID, resultSession = "sess-created-1", "sess-created-1"
	case "session.send", "session.events", "session.control", "session.attach":
		sid, _ := env["session_id"].(string)
		sessionID, resultSession = sid, sid
	}
	fmt.Fprint(w, `{"protocol_version":"researchos-client/2","command_id":"`+commandID+
		`","status":"COMPLETED","session_id":`+jsonNull(sessionID)+`,"revision":7,"error_code":null,"error":null,`+
		`"result":{"method_confirmed":"`+method+`","session_id":`+jsonNull(resultSession)+
		`,"writer_client_id":"probe-client"}}`)
